"""Bind existing reader results to reusable A105 assay assessments.

Numerical inputs are possessed typed components or authenticated source spans.
Assay selection and source interpretations belong to the investigating episode.
This adapter does not manufacture scientific applicability or independent data.
"""
from copy import deepcopy
from gene_annotation_episode.episodic_workflow.root.a101.domain import REF, obj
from gene_annotation_episode.episodic_workflow.root.a101.library.retained_input_authority.literature_assay_inputs import _witness_schema, SOURCE_KINDS
from gene_annotation_episode.episodic_workflow.root.a101.library.retained_input_authority.literature_partner_source_fields import number_selector_schema
from gene_annotation_episode.episodic_workflow.root.a101.library.retained_input_authority.literature_assay_grading import ROLES, REQUIRED_ROLES, assay_grading_input_schema
SOURCE_SCHEMAS = {'literature_rate_cells': ('literature_rate_storage', 'rate_cells_schema'), 'literature_rate_source_cells': ('literature_rate_storage', 'rate_source_cells_schema'), 'literature_rate_source_meaning_cells': ('literature_rate_meaning_delivery', 'rate_source_meaning_cells_schema'), 'literature_rate_observation_cells': ('literature_rate_observation_storage', 'rate_observation_cells_schema'), 'literature_rate_replicate_cells': ('literature_rate_replicate_storage', 'rate_replicate_cells_schema'), 'literature_assay_cells': ('literature_assay_storage', 'assay_cells_schema'), 'literature_controlled_response_component_cells': ('literature_controlled_response_storage', 'controlled_response_cells_schema'), 'literature_compiled_assay_cells': ('literature_compiled_assay_storage', 'compiled_assay_cells_schema'), 'literature_compiled_assay_v2_cells': ('literature_compiled_assay_storage', 'compiled_assay_v2_cells_schema'), 'literature_compiled_assay_v3_cells': ('literature_compiled_assay_storage', 'compiled_assay_v3_cells_schema'), 'literature_completion_time_cells': ('literature_completion_time_storage', 'completion_time_cells_schema'), 'literature_product_partition_cells': ('literature_product_partition_storage', 'product_partition_cells_schema'), 'literature_product_coupling_cells': ('literature_product_coupling_storage', 'product_coupling_cells_schema'), 'literature_endpoint_signal_cells': ('literature_endpoint_signal_storage', 'endpoint_signal_cells_schema'), 'literature_concentration_window_cells': ('literature_concentration_window_storage', 'concentration_window_cells_schema'), 'literature_parent_depletion_cells': ('literature_parent_depletion_storage', 'parent_depletion_cells_schema'), 'literature_stoichiometric_balance_cells': ('literature_stoichiometric_balance_storage', 'stoichiometric_balance_cells_schema'), 'literature_calibration_recovery_cells': ('literature_calibration_recovery_storage', 'calibration_recovery_cells_schema'), 'literature_kinetic_cells': ('literature_kinetic_storage', 'kinetic_cells_schema'), 'literature_kinetic_summary_precision_cells': ('literature_kinetic_summary_precision_storage', 'summary_precision_cells_schema'), 'literature_kinetic_model_cells': ('literature_kinetic_model_storage', 'kinetic_model_cells_schema'), 'literature_rate_grid_cells': ('literature_rate_observation_storage', 'rate_grid_cells_schema'), 'literature_binding_cells': ('literature_binding_storage', 'binding_cells_schema'), 'literature_binding_model_cells': ('literature_binding_model_storage', 'binding_model_cells_schema'), 'literature_binding_interaction_cells': ('literature_binding_interaction_storage', 'binding_interaction_cells_schema'), 'literature_binding_interaction_model_cells': ('literature_binding_interaction_model_storage', 'binding_interaction_model_cells_schema'), 'literature_transport_cells': ('literature_transport_storage', 'transport_response_cells_schema'), 'literature_channel_cells': ('literature_channel_storage', 'channel_cells_schema'), 'literature_ion_discrimination_cells': ('literature_ion_discrimination_storage', 'ion_discrimination_cells_schema'), 'literature_ratio_cells': ('literature_ratio_storage', 'ratio_cells_schema'), 'literature_ratio_source_cells': ('literature_ratio_source_storage', 'ratio_source_cells_schema'), 'literature_gel_component_cells': ('literature_gel_native_contracts', 'gel_cells_schema'), 'literature_amount_cells': ('literature_amount_storage', 'amount_cells_schema'), 'literature_active_site_cells': ('literature_active_site_storage', 'active_site_cells_schema'), 'literature_optical_cells': ('literature_optical_storage', 'optical_cells_schema'), 'literature_partner_cells': ('literature_partner_storage', 'partner_cells_schema')}

def assay_grading_population_schema():
    schema = deepcopy(assay_grading_input_schema())
    props = schema['properties']
    del props['version']
    props.update(source_ref=deepcopy(REF), source_kind={'enum': list(SOURCE_KINDS)})
    received = obj({'kind': {'const': 'received_component'}, 'namespace': {'enum': list(SOURCE_SCHEMAS)}, 'sheet_ref': deepcopy(REF), 'component': {'type': 'string', 'minLength': 1}})
    received['description'] = 'Use a saved numerical reader component, including a single reported kinetic parameter from literature.kinetic.populate: namespace literature_kinetic_cells, its returned sheet_ref, and component numerator_parameter.'
    literal = obj({'kind': {'const': 'source_number'}, 'number': number_selector_schema(), 'unit': _witness_schema(), 'origin': {'enum': ['reported', 'proposed', 'synthetic']}})
    literal['description'] = 'Scalar shortcut for a number followed immediately by its printed unit in the same source representation. A shared table-header unit uses the appropriate typed reader instead. For a reported Km, kcat or catalytic efficiency, literature.kinetic.populate accepts separate number and unit witnesses and returns a received_component for this grader.'
    from gene_annotation_episode.episodic_workflow.root.a101.library.retained_input_authority.experimental_database_measurements import measurement_schema
    props['quantities'] = obj({role: {'anyOf': [deepcopy(received), deepcopy(literal), *([measurement_schema()] if role == 'effect' else []), {'type': 'null'}]} for role in ROLES})
    props['quantities']['required'] = list(REQUIRED_ROLES)
    schema['required'] = list(props)
    props['experiment_ref'] = {**deepcopy(REF), 'x-reference-namespace': 'reference', 'description': 'Possessed source-anchored assay reference identifying this experiment. Reuse it for another assessment of the same experiment; different experiments use distinct references even when they share a protocol type or paper.'}
    support = {**deepcopy(REF), 'x-reference-namespace': 'reference', 'description': 'A source_subjects record (record_type reference) carrying its original source anchor: source_ref, artifact_ref, start, end and quote. Use its same-action @alias or its already saved reference ID.'}
    for criterion in props['interpretations']['properties'].values():
        refs = criterion['properties']['support_refs']
        refs['items'] = deepcopy(support)
        refs['description'] = 'Select the anchored reference records supporting this criterion. An unknown criterion with no supporting passage uses an empty list.'
    props['prediction_model']['anyOf'][0]['properties']['support_refs']['items'] = deepcopy(support)
    schema['required'].append('experiment_ref')
    return schema
